/*Table structure for table `about_us` */

DROP TABLE IF EXISTS `about_us`;

CREATE TABLE `about_us` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `banner_image` text COLLATE utf8mb4_unicode_ci,
  `mission` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vision` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_intro_title` text COLLATE utf8mb4_unicode_ci,
  `company_intro_description` text COLLATE utf8mb4_unicode_ci,
  `inception_banner_image` text COLLATE utf8mb4_unicode_ci,
  `inception_title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inception_details` text COLLATE utf8mb4_unicode_ci,
  `presence_title` text COLLATE utf8mb4_unicode_ci,
  `presence_sub_title` text COLLATE utf8mb4_unicode_ci,
  `presence_banner_image` text COLLATE utf8mb4_unicode_ci,
  `presence_details` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `about_us` */

insert  into `about_us`(`id`,`title`,`banner_image`,`mission`,`vision`,`company_intro_title`,`company_intro_description`,`inception_banner_image`,`inception_title`,`inception_details`,`presence_title`,`presence_sub_title`,`presence_banner_image`,`presence_details`,`created_at`,`updated_at`) values (1,'<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div>With Joy</div>\r\n<div>We Grow Together</div>\r\n<div>We Serve Together</div>\r\n</body>\r\n</html>','/uploads/contents/1689222409_about-bg.jpg','Delivering quality Primary Healthcare and minimize health inequalities and economic setbacks.','An inclusive world-class primary healthcare ecosystem across Bangladesh.','A Social Business Company Since 1996','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p>GRAMEEN KALYAN is a not-for-profit, Social Business Company in the Grameen family of companies; established in 1996, registered with RJSC under the Companies Act (C-388(08)/96) on 06 November 1996 and with NGO Affairs Bureau (No - 1725) on 02 July 2002. Nobel Peace Laureate and Olympic Laurel Professor Muhammad Yunus is the Founder and Chairman of Grameen Kalyan.</p>\r\n<p>Grameen Kalyan&rsquo;s 25 years of experience reveals that, SOCIAL BUSINESS is not only a feasible, effective &amp; financially sustainable model for providing Primary Healthcare in developing countries but also potentially capable of achieving scale maintaining the affordability.</p>\r\n</body>\r\n</html>','/uploads/contents/1689222409_about-annual.jpeg','Enabling and Empowering People to Elevate Themselves Out of Poverty Cycle Since 1996','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p>Currently, Grameen Kalyan is operating through 140 Community Based Health Centers located in 30 districts of Bangladesh. Each year Grameen Kalyan provides healthcare services to around 700,000 (seven hundred thousand) people through its health centers and satellite programs. Besides that, additional 7 million people in rural communities receive free basic healthcare check-up under Grameen Kalyan&rsquo;s domiciliary and school health programs.</p>\r\n<p>In the late nineties, a study revealed that without improvement in healthcare, the poor cannot stay out of poverty for long time. Microcredit could bring them out of poverty but to keep them out of poverty permanently, healthcare inequalities for the poor must be addressed. Observing the reality, Nobel Laureate Prof. Muhammad Yunus, Chairman of Grameen Kalyan undertook an experimental project named &ldquo;Rural Health Program (RHP)&rdquo; in 1993 through Grameen Trust. Upon its success, RHP was handed over to Grameen Kalyan (GK) in 1997 immediately after its inception and since then it has been operating as a core program of Grameen Kalyan.</p>\r\n<p>Over the time, GK has evolved a cost-effective, equitable, self-sustainable and extended rural health program for the indigent people by implementing the concept of community-based health centers, bringing the health outreach services to the doorsteps of the villagers and mobilizing beneficiaries through Micro Health Insurance (MHI) scheme. Along with providing primary healthcare directly, Kalyan has been promoting secondary &amp; tertiary healthcare indirectly through functional referral services.</p>\r\n</body>\r\n</html>','Our Proud Presence','Across the Country','/uploads/contents/1689222409_proud-bg.jpg','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div>\r\n<p>Grameen Kalyan Health Program has successfully initiated a set of grassroots level health infrastructure and health delivery system in which quality, sustainability and coverage of the underprivileged are the central preoccupations. Through its curative &amp; preventive health services, Grameen Kalyan promotes accurate identification of common illness in outpatient settings, strengthens the counselling of healthcare during outreach activities, and performs timely referral services for acutely ill individuals.</p>\r\n</div>\r\n<div>\r\n<p>Grameen Kalyan continues to extend its support for the well-being of Grameen Bank (GB) borrowers, employees and their family members thru providing higher education loan &amp; scholarship to the children of GB Borrowers and rendering medical, household loan and emergency financial assistance to the GB Employees.</p>\r\n</div>\r\n<div>\r\n<p>Grameen Kalyan has always been responsive to facilitate Food, Healthcare services and Relief assistance to the people affected by various Natural calamities and Disasters whenever the country is in need. Combating with Covid-19 Pandemic is also not an exception in this regard.</p>\r\n</div>\r\n<div>\r\n<p>Ever since the inception of Grameen Bank in 1976, Professor Muhammad Yunus was concern of the fact that, health improvement is an indispensable integral part of poverty alleviation. Consequently, Grameen Kalyan&rsquo;s all efforts and initiatives were focused on solving Social Issues like rural healthcare, elevating livelihood, job creation, and other specific social causes.</p>\r\n</div>\r\n<div>\r\n<p>Since 2006, Grameen Kalyan has been actively involved in establishing &amp; promoting Social Business entities operating diverse sectors like Agriculture, Nutrition, Healthcare, Value Chain, RMG, Finance, and Information Technology. Another massive success of Grameen Kalyan was creating around 6000 micro entrepreneurs in the rural economies, namely &ldquo;Nobin Udyokta&rdquo; - Young Entrepreneur Investment Program which was managed from 2014-2020.</p>\r\n</div>\r\n</body>\r\n</html>','2023-07-13 04:26:49','2023-07-19 08:25:40');

