/*Table structure for table `disease_specific_medicares` */

DROP TABLE IF EXISTS `disease_specific_medicares`;

CREATE TABLE `disease_specific_medicares` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `thumb_image` text COLLATE utf8mb4_unicode_ci,
  `banner_image` text COLLATE utf8mb4_unicode_ci,
  `body_image` text COLLATE utf8mb4_unicode_ci,
  `sub_title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `disease_specific_medicares` */

insert  into `disease_specific_medicares`(`id`,`title`,`thumb_image`,`banner_image`,`body_image`,`sub_title`,`description`,`created_at`,`updated_at`) values (1,'General Medicine','/uploads/contents/1689847026_medicine.jpg','/uploads/contents/1689847026_Medicine-1.jpg','/uploads/contents/1689847026_Medicine-2.jpg','Medicine','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div style=\"text-align: justify;\">General Medicine health camps are conducted by MBBS doctors of Grameen Kalyan at its health centers. Diversified patients are treated and get referred for higher facilities from these medicine camps. Among them hypertension, arthritis, gastritis, peptic ulcer, anemia, fungal infection, allergy, skin diseases like eczema, scabies and acne vulgaris, cold fever, bronchial asthma and cardiovascular disease are common. Most of them are non-communicable diseases those are preventable by modifying the lifestyles and risk factors. According to Statistics, around 65% deaths are occurred due to non-communicable diseases across the world. However, Grameen Kalyan refers the complicated cases to reliable tertiary care providers.</div>\r\n</body>\r\n</html>','2023-07-20 09:57:06','2023-07-20 09:57:58');

/*Table structure for table `districts` */

DROP TABLE IF EXISTS `districts`;

CREATE TABLE `districts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `bn_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `geo_district_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `division_id` bigint unsigned NOT NULL,
  `lat` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lon` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `url` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `districts_division_id_foreign` (`division_id`),
  CONSTRAINT `districts_division_id_foreign` FOREIGN KEY (`division_id`) REFERENCES `divisions` (`id`)
