/*Table structure for table `healthcare_services` */

DROP TABLE IF EXISTS `healthcare_services`;

CREATE TABLE `healthcare_services` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `thumb_image` text COLLATE utf8mb4_unicode_ci,
  `banner_image` text COLLATE utf8mb4_unicode_ci,
  `sub_title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `healthcare_services_page_title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `healthcare_services` */

insert  into `healthcare_services`(`id`,`title`,`thumb_image`,`banner_image`,`sub_title`,`description`,`created_at`,`updated_at`,`healthcare_services_page_title`) values (1,'Micro Health Insurance','/uploads/contents/1689844872_grid-1.jpg','/uploads/contents/1689844872_micro-health-insurance.jpg','A Unique Solution','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p>In Amkhola, under Galachipa Upazila of Patuakhali District, Hasna Banu and her 5 family members live in a small house. Her house is in a remote rural area, located three miles away from the main road. Most people&rsquo;s livelihoods like hers come through agriculture and animal rearing. Today, she is worried about her 5-month-pregnant daughter who will see a doctor at Grameen Kalyan health center. The son-in-law left her daughter after two years of marriage for reasons of unsatisfactory dowry forcing her with her mother, Hasna Banu. Finding some complications in her daughter, the Community Health Assistant in the area suggested that she should see the doctor coming that week at their health center.</p>\r\n<p>Upon her visit to the health center, Hasna Banu found the service was fast-moving with her daughter being cared for by the health staff. However, the DMF at the center asked them to come back again for routine check-ups along with some procedural tests. Hearing that, Hasna Banu became hesitant at the thought of bearing extra expenses while considering the risk of expenses for other family members in case they fall sick too. How will she then bear all the costs?</p>\r\n<p>After disclosing her concern to the DMF, she first came to know of Grameen Kalyan&rsquo;s Micro Health Insurance. The DMF suggested, &ldquo;Why don&rsquo;t you take our Micro Health insurance? It will decrease the overall medical cost even more, and make treatment affordable for your daughter and family in the long run.&rdquo;</p>\r\n<p>To enable marginalized and low-income populations to afford the best primary health care, Grameen Kalyan introduced Micro Health Insurance (MHI) scheme. Since the inception of the project, the goal of it has been to focus and work based on people&rsquo;s best interests</p>\r\n<p>By paying only BDT 200 (USD 2.4) for Grameen Bank (GB) borrowers and BDT 300 (USD 3.5) for Non-GB households, one can take an annual health insurance policy. Each health insurance policy covers up to 6 members of a family. According to our data from 2011 to 2020, Kalyan has insured 2,73,574 people under its Micro Health Insurance policy, and the number continues to grow.</p>\r\n<p>The Micro Health Insurance (MHI) cardholders can avail of the following benefits:</p>\r\n<ul>\r\n<li>25% discount on consultation fees;</li>\r\n<li>25% discount on pathological tests available in Grameen Kalyan Health Center;</li>\r\n<li>10% discount on medicine;</li>\r\n<li>20% discount on regular blood sugar tests for diabetic patients;</li>\r\n<li>Quarterly free health check-up at home for six members in the family;</li>\r\n<li>Compensation of up to BDT 2,000 (USD 24) for hospitalization.</li>\r\n</ul>\r\n<p>With MHI cardholders increasing to over 45,855 people annually Grameen Kalyan introduced an option for half-yearly coverage, which has become famous among the rural people due to its cost-friendly package.</p>\r\n</body>\r\n</html>','2023-07-20 09:21:13','2023-07-20 09:25:20',NULL);

