insert  into `homes`(`id`,`badge_image`,`intro_title`,`intro_sub_title_one`,`intro_sub_title_two`,`chairman_thumb_image`,`chairman_speech`,`chairman_name`,`chairman_designation`,`md_thumb_image`,`md_speech`,`md_name`,`md_designation`,`annual_report_banner_image`,`mhi_banner_image`,`created_at`,`updated_at`) values (1,'/uploads/contents/1689070291_glory.png','27+ Years','of Delivering Affordable Healthcare','to Rural Doorsteps Across Bangladesh.','/uploads/contents/1689070291_people-yunus.png','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\nগ্রামীণ অঞ্চলের প্রান্তিক জনগোষ্ঠীর প্রাথমিক স্বাস্থ্যসেবায় সুদূরপ্রসারী পরিবর্তন আনতে রোগ নির্ণয়, চিকিৎসা ব্যবস্থাপনা, তথ্য প্রযুক্তির যথাযথ প্রয়োগ এবং সারা দেশে সাশ্রয়ী মূল্যে মানসম্পন্ন সেবা প্রদান করাই গ্রামীণ কল্যাণ-এর অঙ্গীকার।\r\n</body>\r\n</html>','প্রফেসর মুহাম্মদ ইউনূস','চেয়ারম্যান, গ্রামীণ কল্যাণ।','/uploads/contents/1689070292_people-moin.png','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\nGrameen Kalyan believes in trust, quality and innovation in delivering services. We are on a mission to transform healthcare in Bangladesh at primary, secondary, and tertiary levels. We exist to provide affordable and quality healthcare and well-being services in unreached communities at the bottom of the pyramid, empowering them to get out of the poverty cycle.\r\n</body>\r\n</html>','A K M Moinuddin Chowdhury','Managing Director, Grameen Kalyan.','/uploads/contents/1689070293_annually-bottom.jpg','/uploads/contents/1689070293_micro-health-banner.jpg','2023-07-11 10:11:33','2023-07-11 10:14:52');

