/*Data for the table `members` */

insert  into `members`(`id`,`name`,`designation`,`company`,`profile_photo`,`desc`,`created_at`,`updated_at`,`is_active`) values (1,'Professor Muhammad Yunus','Chairman','Grameen Kalyan','/uploads/members/profile_photo/1643174569_Prof-Muhammad-Yunus.png','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p style=\"text-align: left;\"><span style=\"color: #212529; font-family: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', Arial, \'Noto Sans\', \'Liberation Sans\', sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\'; font-size: 14px; text-align: center;\">Nobel Laureate Professor Muhammad Yunus is the father of both Social Business and Microcredit, the founder of Grameen Bank, and more than 50 other companies in Bangladesh. For his constant innovation and enterprise, Fortune Magazine named Professor Yunus in March 2012 as &ldquo;one of the greatest entrepreneurs of our time.&rdquo; In 2006, Professor Yunus and Grameen Bank were jointly awarded the Nobel Peace Prize. He is the recipient of 61 honorary degrees from universities across 24 countries. He has received 136 awards from 33 countries including state honors from 10 countries. He is one of only seven individuals to have received the Nobel Peace Prize, the United States Presidential Medal of Freedom, and the United States Congressional Gold Medal. He has appeared on the cover of Time Magazine, Newsweek, and Forbes Magazine.</span></p>\r\n</body>\r\n</html>','2022-01-10 00:20:10','2022-02-01 00:53:21',1),(2,'A K M Moinuddin Chowdhury','Managing Director','Grameen Kalyan','/uploads/members/profile_photo/1643174552_A-K-M-Moinuddin-Chowdhury.png','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\" style=\"text-align: left;\"><span lang=\"EN-GB\" style=\"font-family: \'Verdana\', sans-serif; color: black; font-size: 14px;\">Moin Chowdhury pursued his MBA from Cass Business School, City University, London. Post MBA, he worked as a Principal Consultant for Frost &amp; Sullivan, in its London office. <u></u></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left;\"><span lang=\"EN-GB\" style=\"font-family: \'Verdana\', sans-serif; color: black; font-size: 14px;\">Moin was also appointed as the Director of Finance for the Maxwell Stamp Plc- UK and worked for Department for International Development (DFID) projects for 05 years. In addition to this, Moin has managed two more DFID funded projects in collaboration with the Ministry of Finance, Bangladesh. In those projects, his work capacity allowed him the scope to manage all administrative and financial activities. </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left;\"><span lang=\"EN-GB\" style=\"font-family: \'Verdana\', sans-serif; color: black; font-size: 14px;\">Moin joined Grameen Kalyan in November 2018. It has been a tremendously interesting journey so far! He believes in the principles of &ldquo;Equal Health Care for All&rdquo; and embraces this as a charter in the everyday work. He shares a common philosophy with the Nobel Laureate Professor Muhammad Yunus of making a difference to somebody\'s life and helping them find their voice.</span></p>\r\n</body>\r\n</html>','2022-01-10 00:22:35','2022-02-01 00:50:32',1),(3,'S.M. Huzzatul Islam Latifee','Director','Grameen Kalyan','/uploads/members/profile_photo/1643174534_S.M.-Huzzatul-Islam-Latifee.png','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div class=\"OutlineElement Ltr SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: \'Segoe UI\', \'Segoe UI Web\', Arial, Verdana, sans-serif; font-size: 12px;\">\r\n<p class=\"Paragraph SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow-wrap: break-word; white-space: pre-wrap; vertical-align: baseline; font-kerning: none; background-color: transparent; color: windowtext;\"><span style=\"font-size: 14px;\"><span class=\"TextRun SCXW70143503 BCX0\" lang=\"EN-US\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; color: #616161; line-height: 17.2667px; font-family: Montserrat, Montserrat_EmbeddedFont, Montserrat_MSFontService, sans-serif;\" xml:lang=\"EN-US\" data-contrast=\"none\"><span class=\"NormalTextRun SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\">Professor H. I. </span><span class=\"NormalTextRun SpellingErrorV2 SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlSpellingErrorV2,); border-bottom: 1px solid transparent;\">Latifee</span><span class=\"NormalTextRun SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> currently works as the Adviser to Grameen </span><span class=\"NormalTextRun SpellingErrorV2 SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlSpellingErrorV2,); border-bottom: 1px solid transparent;\">Shikkha</span><span class=\"NormalTextRun SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\">. He served the University of Chittagong as a Professor of Economics before he joined Grameen Trust (GT) as its Managing Director in January 1994. He was the Chairman of the Department of Economics at the University of Chittagong from 1991-1994 and Proctor of the University from 1988-1991. Professor </span><span class=\"NormalTextRun SpellingErrorV2 SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlSpellingErrorV2,); border-bottom: 1px solid transparent;\">Latifee</span><span class=\"NormalTextRun SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> as the Managing Director of Grameen Trust (January 1994 to </span><span class=\"NormalTextRun ContextualSpellingAndGrammarErrorV2 SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlContextualSpellingAndGrammarErrorV2,); border-bottom: 1px solid transparent;\">December,</span><span class=\"NormalTextRun SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> 2016) provided leadership in the establishment and implementation of more than 151 Grameen replication programs in 41 countries. He also guided the New Entrepreneur Program of Grameen Trust, which demonstrated a tremendous success for solving the problem of youth unemployment and promoting young entrepreneurs since its inception in 2013.</span></span><span class=\"EOP SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; line-height: 17.2667px; font-family: Montserrat, Montserrat_EmbeddedFont, Montserrat_MSFontService, sans-serif; color: #616161;\" data-ccp-props=\"{&quot;201341983&quot;:0,&quot;335551550&quot;:1,&quot;335551620&quot;:1,&quot;335559739&quot;:160,&quot;335559740&quot;:259}\">&nbsp;</span></span></p>\r\n<p class=\"Paragraph SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow-wrap: break-word; white-space: pre-wrap; vertical-align: baseline; font-kerning: none; background-color: transparent; color: windowtext;\">&nbsp;</p>\r\n</div>\r\n<div class=\"OutlineElement Ltr SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: \'Segoe UI\', \'Segoe UI Web\', Arial, Verdana, sans-serif; font-size: 12px;\">\r\n<p class=\"Paragraph SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow-wrap: break-word; white-space: pre-wrap; vertical-align: baseline; font-kerning: none; background-color: transparent; color: windowtext;\"><span class=\"TextRun SCXW70143503 BCX0\" lang=\"EN-US\" style=\"margin: 0px; padding: 0px; user-select: text; font-variant-numeric: normal; font-variant-east-asian: normal; color: #616161; font-size: 14px; line-height: 17.2667px; font-family: Montserrat, Montserrat_EmbeddedFont, Montserrat_MSFontService, sans-serif;\" xml:lang=\"EN-US\" data-contrast=\"none\"><span class=\"NormalTextRun SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\">Professor </span><span class=\"NormalTextRun SpellingErrorV2 SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlSpellingErrorV2,); border-bottom: 1px solid transparent;\">Latifee</span><span class=\"NormalTextRun SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> is the winner of Business Week&rsquo;s Stars of Asia Award, 2001. He has been a longtime associate of Nobel Laureate Professor Muhammad Yunus, father of Microcredit, founder of Grameen Bank and the father of Social Business. Professor </span><span class=\"NormalTextRun SpellingErrorV2 SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlSpellingErrorV2,); border-bottom: 1px solid transparent;\">Latifee</span><span class=\"NormalTextRun SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> serves as Member of </span><span class=\"NormalTextRun AdvancedProofingIssueV2 SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlAdvancedProofingIssueV2,); border-bottom: 1px solid transparent;\">a number of</span><span class=\"NormalTextRun SCXW70143503 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> Boards of different microfinance organizations and social business entities in Bangladesh and other countries including Grameen America Inc.</span></span></p>\r\n</div>\r\n</body>\r\n</html>','2022-01-10 00:23:49','2022-02-01 00:52:34',1),(4,'Nurjahan Begum','Director','Grameen Kalyan','/uploads/members/profile_photo/1643174518_Nurjahan-Begum.png','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\"><span lang=\"EN\" style=\"font-size: 14px;\">Ms. Nurjahan Begum, one of the earliest associates of Nobel Laureate Professor Muhammad Yunus during the establishment of Grameen Bank, served as Acting Managing Director of the bank and Principal of Grameen Bank Central Training Institute. She served as Managing Director of Grameen Shakti and Grameen Shikkha and is currently working as Advisor to Professor Yunus besides serving several Grameen organizations as chairperson, director or trustee. She also served Grameenphone Ltd., Bangladesh and Grameen Foundation, USA as director and is currently serving as director of Grameen Italia Foundation, Italy and Center for Mass Education in Science (CMES), Bangladesh. </span></p>\r\n<p class=\"MsoNormal\"><span style=\"font-size: 14px;\"><span lang=\"EN\">She was awarded the <strong style=\"mso-bidi-font-weight: normal;\">Susan M. Davis Lifetime Achievement Award 2008 </strong>by Grameen Foundation, the <strong style=\"mso-bidi-font-weight: normal;\">World Summit Millennium Development Goals Award 2009</strong>, the </span><strong style=\"mso-bidi-font-weight: normal;\"><span lang=\"EN-US\">Vision Award 2009, </span></strong><span lang=\"EN-US\">the <strong style=\"mso-bidi-font-weight: normal;\">Outstanding Contribution to Education Award</strong> at Ed Leadership 7<sup>th</sup> International Roundtable 2014, and the <strong style=\"mso-bidi-font-weight: normal;\">Yunus Social Business Summit Award </strong>in 2017. She participated in the <strong style=\"mso-bidi-font-weight: normal;\">Fortune Most Powerful Women Summit</strong> held in Los Angeles in 2007 and was appointed President to the <strong style=\"mso-bidi-font-weight: normal;\">Foundation for Justice Prize</strong> giving ceremony held in Valencia, Spain in 2007.</span></span></p>\r\n</body>\r\n</html>','2022-01-10 00:24:17','2022-01-30 19:07:57',1),(5,'M Shahjahan','Director','Grameen Kalyan','/uploads/members/profile_photo/1643174502_M-Shahjahan.png','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div class=\"OutlineElement Ltr SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: \'Segoe UI\', \'Segoe UI Web\', Arial, Verdana, sans-serif; font-size: 12px;\">\r\n<p class=\"Paragraph SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow-wrap: break-word; white-space: pre-wrap; vertical-align: baseline; font-kerning: none; background-color: transparent; color: windowtext;\"><span style=\"font-size: 14px;\"><span class=\"TextRun SCXW262065907 BCX0\" lang=\"EN-US\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; color: #616161; line-height: 17.2667px; font-family: Montserrat, Montserrat_EmbeddedFont, Montserrat_MSFontService, sans-serif;\" xml:lang=\"EN-US\" data-contrast=\"none\"><span class=\"NormalTextRun SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\">M Shahjahan is the advisor to Chairperson Professor Muhammed Yunus as well as Managing Director of Grameen Telecom Trust. Earlier he was the Managing Director (CEO) of Grameen Bank. He acted as the Managing Director of Grameen Bank from 14 August 2011 to 30 October 2015. Now, he is </span><span class=\"NormalTextRun ContextualSpellingAndGrammarErrorV2 SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlContextualSpellingAndGrammarErrorV2,); border-bottom: 1px solid transparent;\">on</span><span class=\"NormalTextRun SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> retirement. Earlier, he served as the Deputy Managing Director, the General Manager and Head of the Accounts, Finance, Planning, Monitoring and Evaluation Division, the Chief of the Audit Department, and the Zonal Manager of Grameen Bank.</span></span><span class=\"EOP SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; line-height: 17.2667px; font-family: Montserrat, Montserrat_EmbeddedFont, Montserrat_MSFontService, sans-serif; color: #616161;\" data-ccp-props=\"{&quot;201341983&quot;:0,&quot;335551550&quot;:1,&quot;335551620&quot;:1,&quot;335559739&quot;:160,&quot;335559740&quot;:259}\">&nbsp;</span></span></p>\r\n<p class=\"Paragraph SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow-wrap: break-word; white-space: pre-wrap; vertical-align: baseline; font-kerning: none; background-color: transparent; color: windowtext;\">&nbsp;</p>\r\n</div>\r\n<div class=\"OutlineElement Ltr SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: \'Segoe UI\', \'Segoe UI Web\', Arial, Verdana, sans-serif; font-size: 12px;\">\r\n<p class=\"Paragraph SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow-wrap: break-word; white-space: pre-wrap; vertical-align: baseline; font-kerning: none; background-color: transparent; color: windowtext;\"><span style=\"font-size: 14px;\"><span class=\"TextRun SCXW262065907 BCX0\" lang=\"EN-US\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; color: #616161; line-height: 17.2667px; font-family: Montserrat, Montserrat_EmbeddedFont, Montserrat_MSFontService, sans-serif;\" xml:lang=\"EN-US\" data-contrast=\"none\"><span class=\"NormalTextRun SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\">Mr. Shahjahan is a member of the Board of Directors of several companies that work in the fields of health, education, agriculture, welfare, renewable energy and telecommunications. He obtained a Bachelor of Commerce (Honours) degree in Accounting from the University of Dhaka in 1976, as well as a </span><span class=\"NormalTextRun ContextualSpellingAndGrammarErrorV2 SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlContextualSpellingAndGrammarErrorV2,); border-bottom: 1px solid transparent;\">Master&rsquo;s</span><span class=\"NormalTextRun SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> degree in </span><span class=\"NormalTextRun ContextualSpellingAndGrammarErrorV2 SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlContextualSpellingAndGrammarErrorV2,); border-bottom: 1px solid transparent;\">Accounting</span><span class=\"NormalTextRun SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> in 1977 and a </span><span class=\"NormalTextRun ContextualSpellingAndGrammarErrorV2 SCXW262065907 BCX0 GrammarErrorHighlight\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; color: var(--clrsquigglehighlighttextcolor,#000000); background-repeat: repeat-x; background-position: left bottom; border-bottom: 1px solid transparent;\">Master&rsquo;s</span><span class=\"NormalTextRun SCXW262065907 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> degree in Finance in 1981. He was awarded ICAB Medal (Silver) for passing the &lsquo;C.A. Intermediate&rsquo; examination at the earliest eligible chance in 1981.</span></span> </span></p>\r\n</div>\r\n</body>\r\n</html>','2022-01-10 00:24:42','2022-02-01 00:52:02',1),(6,'Md. Ashraful Hassan','Director','Grameen Kalyan','/uploads/members/profile_photo/1643174482_Md.-Ashraful-Hassan.png','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p style=\"text-align: left;\"><span style=\"font-size: 14px;\"><span lang=\"EN-US\" style=\"line-height: 107%; font-family: \'Segoe UI\', sans-serif; color: #242424; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Ashraful Hassan has been working with Grameen Group for the last 36 </span><span lang=\"EN-US\" style=\"line-height: 107%; font-family: \'Segoe UI\', sans-serif; color: #242424;\"><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">years. He currently serves as Managing Director of Ononoyo Construction &amp; Developments Ltd. (a concern of Grameen Group) and is </span><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">engaged to construct &amp; develop all projects of Grameen Group. He also </span><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">serves as Executive Vice Chairman of Grameen Telecom, Grameen </span><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Distribution Ltd. Grameen Shamogree, Grameen Knitwear Ltd. Grameen Fabrics &amp; Fashions Ltd., </span><span style=\"background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">and CEO of Grameen Telecom Trust.</span></span></span></p>\r\n</body>\r\n</html>','2022-01-10 00:25:08','2022-02-01 00:51:51',1),(8,'Nazneen Sultana','Director','Grameen Kalyan','/uploads/members/profile_photo/1643174367_Nazneen-Sultana.png','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p style=\"margin: 0cm 0cm 15pt; text-align: left;\"><span lang=\"EN-US\" style=\"font-size: 14px; font-family: \'Times New Roman\', serif;\">Ms. Nazneen Sultana has been serving as the Managing Director and the Chief Executive Officer of Grameen Communications since its inception in 1997. At Grameen Communications, she led various projects for reaching ICT to the remote villages, development of world&rsquo;s first &amp; complete micro banking software that&rsquo;s been being used by more than 175 MFIs including Grameen Bank. She was also actively involved in formation of some social business companies i.e. euglena (Formerly, GrameenYukiguniMaitake Ltd).</span></p>\r\n<p style=\"margin: 0cm 0cm 15pt; text-align: left;\"><span lang=\"EN-US\" style=\"font-size: 14px; font-family: \'Times New Roman\', serif;\">Having completed BS and MS in Applied Mathematics from University of Chittagong, Bangladesh, she started her career at Grameen Bank and established ICT wing of the Bank. Meanwhile, she achieved a diploma in Management Information Systems from Asian Institute of Technology, Thailand. Having experience in IT field for more than 30 years, she has been serving as Director of different IT companies including Accenture Bangladesh. Moreover, she serves as executive member of NGOs that deal with gender issues, affordable healthcare for poor, women empowerment and ICT for development</span></p>\r\n</body>\r\n</html>','2022-01-10 00:25:53','2022-02-01 00:51:27',1),(9,'Abdul Hai Khan','Director','Grameen Kalyan','/uploads/members/profile_photo/1643174242_Abdul-Hai-Khan.png','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div class=\"OutlineElement Ltr SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: \'Segoe UI\', \'Segoe UI Web\', Arial, Verdana, sans-serif; font-size: 12px;\">\r\n<p class=\"Paragraph SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow-wrap: break-word; white-space: pre-wrap; vertical-align: baseline; font-kerning: none; background-color: transparent; color: windowtext;\"><span style=\"font-size: 14px;\"><span class=\"TextRun SCXW15146824 BCX0\" lang=\"EN-US\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; color: #616161; line-height: 17.2667px; font-family: Montserrat, Montserrat_EmbeddedFont, Montserrat_MSFontService, sans-serif;\" xml:lang=\"EN-US\" data-contrast=\"none\"><span class=\"NormalTextRun SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\">Abdul Hai Khan, practitioner of microfinance and social business, joined Grameen Trust (GT) as the Managing Director on January 1, 2017. He started his career in Grameen Bank as the Branch Manager and got </span><span class=\"NormalTextRun ContextualSpellingAndGrammarErrorV2 SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlContextualSpellingAndGrammarErrorV2,); border-bottom: 1px solid transparent;\">number</span><span class=\"NormalTextRun SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> of promotions </span><span class=\"NormalTextRun ContextualSpellingAndGrammarErrorV2 SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlContextualSpellingAndGrammarErrorV2,); border-bottom: 1px solid transparent;\">i.e.</span><span class=\"NormalTextRun SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> Program Officer, Area Manager, Assistant General Manager and Deputy General Manager. He had the opportunity to perform his responsibility also as a Zonal Manager of Grameen Bank where he supervised all Branches and Area Offices and more than 1000 staff of that respective Zone of Grameen Bank.</span></span><span class=\"EOP SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; line-height: 17.2667px; font-family: Montserrat, Montserrat_EmbeddedFont, Montserrat_MSFontService, sans-serif; color: #616161;\" data-ccp-props=\"{&quot;201341983&quot;:0,&quot;335551550&quot;:1,&quot;335551620&quot;:1,&quot;335559739&quot;:160,&quot;335559740&quot;:259}\">&nbsp;</span></span></p>\r\n<p class=\"Paragraph SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow-wrap: break-word; white-space: pre-wrap; vertical-align: baseline; font-kerning: none; background-color: transparent; color: windowtext;\">&nbsp;</p>\r\n</div>\r\n<div class=\"OutlineElement Ltr SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: \'Segoe UI\', \'Segoe UI Web\', Arial, Verdana, sans-serif; font-size: 12px;\">\r\n<p class=\"Paragraph SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow-wrap: break-word; white-space: pre-wrap; vertical-align: baseline; font-kerning: none; background-color: transparent; color: windowtext;\"><span class=\"TextRun SCXW15146824 BCX0\" lang=\"EN-US\" style=\"margin: 0px; padding: 0px; user-select: text; font-variant-numeric: normal; font-variant-east-asian: normal; color: #616161; font-size: 14px; line-height: 17.2667px; font-family: Montserrat, Montserrat_EmbeddedFont, Montserrat_MSFontService, sans-serif;\" xml:lang=\"EN-US\" data-contrast=\"none\"><span class=\"NormalTextRun SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\">Mr. Khan has a wide range of </span><span class=\"NormalTextRun ContextualSpellingAndGrammarErrorV2 SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlContextualSpellingAndGrammarErrorV2,); border-bottom: 1px solid transparent;\">experiences</span><span class=\"NormalTextRun SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> on GT&rsquo;s worldwide replication programs following Grameen Bank Approach (GBA). He was the CEO of Kosovo Grameen </span><span class=\"NormalTextRun SpellingErrorV2 SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; background-repeat: repeat-x; background-position: left bottom; background-image: var(--urlSpellingErrorV2,); border-bottom: 1px solid transparent;\">Missione</span><span class=\"NormalTextRun SCXW15146824 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent;\"> Arcobaleno Microcredit Fund (KGMAMF) in Kosovo from 2003-2005 and General Manager of Family Bank in Bahrain from 2009-2011. He has conducted many international training programs on various issues on Microcredit and Social Business in different countries as well as monitoring and evaluation visits to the microcredit projects run, owned and/or managed by GT worldwide. He also conducted a &lsquo;Fact Finding Mission&rsquo; in Nepal in 2013.</span></span></p>\r\n</div>\r\n</body>\r\n</html>','2022-01-10 00:26:14','2022-02-01 00:51:13',1),(10,'Lamiya Morshed','Director','Grameen Kalyan','/uploads/members/profile_photo/1643174222_Lamiya-Morshed.png','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p style=\"margin-bottom: 0cm; text-align: left;\"><span lang=\"EN-US\" style=\"font-family: Arial, sans-serif; font-size: 14px;\">Ms Lamiya Morshed has been the Executive Director of Yunus Centre, the global think tank for Social Business activities established by Nobel Laureate Professor Muhammad Yunus. With 24 years of experience with Grameen, she is the Executive Director of Grameen Healthcare Trust and board member to multiple Yunus and Grameen such as the Grameen Creative Lab, Grameen Caledonian College of Nursing, Grameen Euglena Ltd. and YY Ventures.</span></p>\r\n<p style=\"margin-bottom: 0cm; text-align: left;\">&nbsp;</p>\r\n<p style=\"margin-bottom: 0cm; text-align: left;\"><span lang=\"EN-US\" style=\"font-family: Arial, sans-serif; font-size: 14px;\">Ms. Lamiya Morshed is a graduate in Economics from London School of Economics and Political Science and speaks four languages.</span></p>\r\n</body>\r\n</html>','2022-01-10 00:26:32','2022-02-01 00:51:01',1),(11,'Mir Akhter Hossain','Director','Grameen Kalyan','/uploads/members/profile_photo/1643192907_Mir-Akhter-Hossain.png','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div class=\"OutlineElement Ltr SCXW143684397 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow: visible; cursor: text; clear: both; position: relative; direction: ltr; font-family: \'Segoe UI\', \'Segoe UI Web\', Arial, Verdana, sans-serif; font-size: 12px;\">\r\n<p class=\"Paragraph SCXW143684397 BCX0\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; overflow-wrap: break-word; white-space: pre-wrap; vertical-align: baseline; font-kerning: none; background-color: transparent; color: windowtext; text-align: left;\"><span style=\"font-size: 14px;\"><span class=\"TextRun SCXW143684397 BCX0\" lang=\"EN-US\" style=\"margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; color: windowtext; line-height: 17.26