/*Table structure for table `services` */

DROP TABLE IF EXISTS `services`;

CREATE TABLE `services` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `homepage_thumb_image` text COLLATE utf8mb4_unicode_ci,
  `servicepage_thumb_image` text COLLATE utf8mb4_unicode_ci,
  `sub_title_one` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sub_title_two` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `short_description` text COLLATE utf8mb4_unicode_ci,
  `service_detail_banner_image` text COLLATE utf8mb4_unicode_ci,
  `service_detail_slogan` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `long_description` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `service_detail_sub_title` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `services` */

insert  into `services`(`id`,`title`,`homepage_thumb_image`,`servicepage_thumb_image`,`sub_title_one`,`sub_title_two`,`short_description`,`service_detail_banner_image`,`service_detail_slogan`,`long_description`,`created_at`,`updated_at`,`service_detail_sub_title`) values (1,'Healthcare','/uploads/contents/1689758543_service-1.png','/uploads/contents/1689758544_health-care.jpg','Healthy and happy communities thrive to prosper eventually','Healthcare at Doorsteps','Grameen Kalyan has become known for delivering affordable primary healthcare through community-based health centres and outreach health programs among rural communities to reduce health inequalities in urban and rural areas.','/uploads/contents/1689758544_healthcare-bg.jpg','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div>Serving People with</div>\r\n<div>Empathy</div>\r\n<div>Quality &amp;</div>\r\n<div>Trust</div>\r\n</body>\r\n</html>','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n\r\n</body>\r\n</html>','2023-07-19 09:22:24','2023-08-06 10:18:43',NULL),(2,'<!DOCTYPE html>\n<html>\n<head>\n</head>\n<body>\nWell-Being\n</body>\n</html>','/uploads/contents/1689843876_service-2.png','/uploads/contents/1689843876_well-1.jpg','Achieving dreams to make bigger difference','Well-being for a Better Future','Grameen Kalyan has become known for delivering affordable primary healthcare through community-based health centres and outreach health programs among rural communities to reduce health inequalities in urban and rural areas.','/uploads/contents/1689843877_well-being-min.jpg','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\nWell-Being <br />For A Better Future\r\n</body>\r\n</html>','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p>With a vision of bringing equity in marginalised communities in Bangladesh, Grameen Kalyan not only encased its activity within healthcare services but also aims to bring a change in other sectors.</p>\r\n<p>Extending its backing for the well-being of Grameen Bank borrowers, employees and their family members, Kalyan provides financial support to Grameen Bank (GB) to undertake several programs for the welfare of the GB stakeholders. By offering scholarships and higher education loans to the children of GB borrowers and welfare loans to GB employees, Kalyan is significantly contributing to achieving the dreams of GB families.</p>\r\n<h4>FOR GB MEMBERS:</h4>\r\n<table>\r\n<thead>\r\n<tr>\r\n<th>Higher Education Loan</th>\r\n<th>Higher Education Loan</th>\r\n<th>Higher Education Loan</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>BDT 2,685 million</td>\r\n<td>BDT 2,685 million</td>\r\n<td>BDT 2,685 million</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Higher Education Loan:</p>\r\n<p>As Grameen Bank strengthens its borrowers\' ability to support themselves and their families through microloans, Grameen Kalyan aims to support their children\'s achievement and other forms of academic success. Kalyan encourages children aspiring to pursue higher education with any means of financial support, for example paying an interest subsidy for higher education loans taken by GB borrowers. Up till the end of&nbsp;December 2021, Kalyan has provided a sum of over&nbsp;BDT 2,685 million (USD 33.70 million)&nbsp;as a subsidy for higher education loans. GB initially calculates 12% interest for this loan, of which the students pay only 5% applicable after the completion of their study. Meanwhile, Kalyan pays the entire 12% interest subsidy to GB during their education period and pays 7% interest subsidy after the end of their study till the loan payback is completed.</p>\r\n<p>Scholarship program:</p>\r\n<p>Focused on incentivising the education of Grameen Bank borrowers&rsquo; and members&rsquo; children; Grameen Kalyan started its scholarship program back then in 1996. Kalyan awards scholarships in the following categories to the children for their outstanding performances in -</p>\r\n<ul>\r\n<li>Primary School Scholarship</li>\r\n<li>SSC Scholarship</li>\r\n<li>HSC Scholarship</li>\r\n<li>Sports &amp; Cultural Activities</li>\r\n</ul>\r\n<p>From 1996 to&nbsp;December 2021, Kalyan has contributed&nbsp;BDT 654 million (USD 7.69 million)&nbsp;for this program.</p>\r\n<p>Support to Grameen Bank Emergency Fund:</p>\r\n<p>Grameen Bank maintains a central emergency fund to extend support to the GB borrowers\' families for funeral costs and other related costs after the death of its borrower. When there is any shortfall in the GB fund, Kalyan covers the rest. Up till December 2021, Kalyan supported and donated BDT 217.7 million (USD 2.56 million) to GB\'s central emergency fund.</p>\r\n<h4>FOR GB EMPLOYEES:</h4>\r\n<table>\r\n<thead>\r\n<tr>\r\n<th>Medical loan (For GB Employees):</th>\r\n<th>Home appliance loan(For GB Employees) :</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>BDT 18.50 million</td>\r\n<td>BDT 1,257.60 million</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Medical loan:</p>\r\n<p>Grameen Kalyan provides interest subsidies for medical loans borrowed by GB employees for themselves and their family members. Out of 12% imposed interest on the loan, a GB employee has to pay only 5% interest while Kalyan covers the rest 7% as a subsidy on behalf of the GB employees. Till December 2021, Kalyan has contributed BDT 18.50 million (USD 0.22 million) against this loan.</p>\r\n<p>Home appliance loan:</p>\r\n<p>Grameen Kalyan also pays interest subsidies for home appliance loans. For this loan, a GB employee pays 5% interest, and on behalf of the employee, Kalyan pays the remaining 7% interest as a subsidy to GB until the loan is paid back. As of December 2021, Kalyan has paid&nbsp;BDT 1257.60 million (USD 14.79 million)&nbsp;for home appliance loans.</p>\r\n<p>Apart from these, Kalyan undertakes different well-being programs which impact GB borrowers and members in the long run.<br /><br /></p>\r\n<h4>LOAN GUARANTEE FOR NURSING COLLEGE STUDENTS:</h4>\r\n<p>Grameen Kalyan provides a loan guarantee to the children of Grameen Bank borrowers who enrol in Grameen Caledonian College of Nursing (GCCN) thru GB education loan. The education loan is available to the students who can demonstrate their financial necessity and whose mothers have been GB Borrowers for at least two years.</p>\r\n<p>Students who get GB Education Loan are responsible for all accrued interest and the loan principles; but they must have a loan guarantor. Here&rsquo;s where Grameen Kalyan comes into play. As a guarantor of these loans, Kalyan ensures their smooth and uninterrupted nursing education. Up till now, Grameen Kalyan has provided more than 950 loan guarantee letters to the GCCN students; among them 595 students have completed their Diploma &amp; B.Sc. graduation and the rest are enrolling.</p>\r\n</body>\r\n</html>','2023-07-20 09:04:37','2023-07-20 09:04:37',NULL);

/*Table structure for table `sessions` */

