/*Data for the table `stories` */

insert  into `stories`(`id`,`title`,`category_id`,`thumb_image`,`banner_image`,`desc`,`is_active`,`created_at`,`updated_at`) values (1,'Fighting the Pandemic',2,'/uploads/story/thumb_image/1643943164_ftp.jpg','/uploads/story/banner_image1643943164_ftp.jpg','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">The coronavirus outbreak occurred worldwide at the end of 2019, and Bangladesh was hit by the deadly virus in March 2020. As the fast-spreading coronavirus claimed many lives and affected people countrywide, Grameen Kalyan did not place a hold on the primary healthcare services for the sake of people. During this pandemic, Grameen Kalyan\'s doctors and health workers diligently took all the possible precautions, wearing masks, gloves and other PPE gear, to continue to serve the patients. Alongside the doctors, Community Health Assistants carried out their routine check-ups risking their lives visiting households and assisting patients at the healthcare centers. </span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Varying from young to elderly, most of our service recipients are underprivileged and come from the most marginalised fractions of the society. The women, in these already disadvantaged households, are further overlooked by the mainstream healthcare providers in Bangladesh. They have fallen victim to exclusion and vulnerability during this pandemic. During this time of the pandemic, healthcare providers like Grameen Kalyan became more essential than ever before. With appropriate health safety measures taken, primary healthcare has been playing quite an important and effective role in the current critical circumstance.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Grameen Kalyan started distributing informative awareness leaflets to patients and other community members about the countrywide upsurge of Covid 19. These leaflets made patients and community members aware of the symptoms and preventive measures against the disease. The leaflets ensured that these people could access information about the condition more quickly and earlier on. Other than distributing leaflets, Grameen Kalyan distributed free non-medical masks and gloves amongst patients and community members. For some of them, this was the only means of access to such preventive equipment. Doctors also carried out regular check-ups and continuous tests to ensure that these patients were not suffering from fever or any other signs of Covid 19. Free rations and food packages were also distributed amongst the communities at regular intervals to counter the food shortages that became prevalent during the initial Covid outbreak.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><strong><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span></strong><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><strong><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span></strong><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><strong><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">The People Served:&nbsp;</span></strong><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-GB; mso-fareast-language: EN-AU;\">&nbsp;</span></span></p>\r\n<table style=\"border-collapse: collapse; width: 100%; height: 280px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 9.07258%; height: 18px;\">&nbsp;</td>\r\n<td style=\"width: 40.9274%; height: 18px;\">Items</td>\r\n<td style=\"width: 25%; height: 18px;\">Amount</td>\r\n<td style=\"width: 25%; height: 18px;\">BDT</td>\r\n</tr>\r\n<tr style=\"height: 46px;\">\r\n<td style=\"width: 