dth: 25%; height: 54px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">Hip Joint</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 54px;\">&nbsp;</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 25%; height: 18px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">HBsAg</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 18px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">R.A.</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 18px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">Elbow Joint B/V</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 18px;\">&nbsp;</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 25%; height: 36px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">Serum Creatinine</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 36px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">T.P.H.A&nbsp;</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 36px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">Wrist Joint B/V</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 36px;\">&nbsp;</td>\r\n</tr>\r\n<tr style=\"height: 123px;\">\r\n<td style=\"width: 25%; height: 123px;\">\r\n<p class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; margin-bottom: 0cm; line-height: normal; vertical-align: baseline;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; font-family: Arial, sans-serif;\">Medical Check UP package&nbsp;</span><span style=\"font-size: 12pt; font-family: Arial, sans-serif;\">&nbsp;</span></p>\r\n<span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">[CP, Urine R/E, RBS, VDRL, HBsAg screening]</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 123px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">Blood Urea</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 123px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">Knee Joint B/V</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 123px;\">&nbsp;</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 25%; height: 36px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">Pregnancy Test (Strip)</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 36px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">SGPT</span></td>\r\n<td style=\"width: 25%; height: 36px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">Ankle Joint B/V</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 36px;\">&nbsp;</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 25%; height: 18px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">BT, CT</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 18px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">Serum Uric Acid</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 18px;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">Any Fracture B/V</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%; height: 18px;\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 25%;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%;\"><span lang=\"EN-GB\" style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">Foot B/V</span><span style=\"font-size: 12pt; line-height: 107%; font-family: Arial, sans-serif;\">&nbsp;</span></td>\r\n<td style=\"width: 25%;\">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</body>\r\n</html>',1,'2022-01-07 00:45:18','2022-02-04 16:50:45'),(3,'Compliance is Priority',4,'/uploads/story/thumb_image/1644390242_Compliance_is_priority.JPG','/uploads/story/banner_image1644390246_Compliance_is_priority.JPG','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">By providing an affordable and better healthcare experience to every individual under our care, we are determined to provide the best experience to every visitor of our health centers. Maintaining the trust and expectation of our patients, we aspire to give the best service that a healthcare center could offer.&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Doing so, Grameen Kalyan never compromises to maintain the legal, ethical and professional standards and government-approved guidelines for conducting Primary Healthcare Services across the country.&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Each of our health centers undergoes a rigorous process of evaluations and safety checks to be an established institute that abides by the health and safety protocols. At Grameen Kalyan, we pay strict and close attention to retaining license coverage, maintaining uniform Health Center infrastructure and interior. Alongside, we follow systematic hygiene &amp; cleanliness, waste management, preserving pathological instruments, reagents, medicines and overall treatment protocols to ensure quality care and maintain patient satisfaction.</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n</body>\r\n</html>',1,'2022-01-07 00:53:25','2022-02-09 21:04:07'),(4,'Emergency Response',1,'/uploads/story/thumb_image/1670303592_EMERGENCY_RESPONSE-small.jpg','/uploads/story/banner_image1643942462_thumbnail_emergency_response-1.jpg','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Based on our years of experience responding to health emergencies caused by natural or man-made disasters, Grameen Kalyan has become a renowned, on-the-ground, emergency response organization in Bangladesh. Through reducing response times and empowering local networks, we try to assist areas impacted by providing free primary medical care and food support as a part of our emergency response initiative and</span> <span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Disaster Management Program.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">For the last 25 years, the country has faced severe annual floods and various natural catastrophes, for example, the deadly cyclone of 2007, Sidr, and other such calamities. Grameen Kalyan always tries its best to reach the affected rural areas adjacent to its health centers and arrange free medical camps and food support programs. </span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">In 2013, Bangladesh witnessed the fatal Rana Plaza tragedy, a Ready-made Garments building that crashed down taking numerous lives and injuring hundreds. As the number of injured during the incident spiked along with deaths, Grameen Kalyan set up a week-long medical booth and rendered urgent primary treatment to the wounded. Moreover, when half a million Rohingya entered Bangladesh seeking refuge and shelter from Rakhine State, Myanmar, on 25 August 2017, Grameen Kalyan stepped in to support during the crisis. Along with local Bangladeshi communities, Grameen Kalyan also took part in the multinational aid effort led by the Government of Bangladesh to overcome the crisis and sustain the refugees.</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Grameen Kalyan&rsquo;s efforts to serve people during emergency crises set a model of empathy. It has been improving, strengthening and transforming its current health program in a sustainable, impartial and regulated way, aiming to respond to future disasters as well.&nbsp; </span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\">&nbsp;</p>\r\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"1\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 33.3333%;\">Incidents</td>\r\n<td style=\"width: 33.3333%;\">People Served&nbsp;</td>\r\n<td style=\"width: 33.3333%;\">Ewlief Amount</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 33.3333%;\">Flood, 2017</td>\r\n<td style=\"width: 33.3333%;\">15,299</td>\r\n<td style=\"width: 33.3333%;\">4,21,065</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 33.3333%;\">Flood, 2020</td>\r\n<td style=\"width: 33.3333%;\">2,030</td>\r\n<td style=\"width: 33.3333%;\">2,02,799</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 33.3333%;\">Rana Plaza Incident</td>\r\n<td style=\"width: 33.3333%;\">1,300</td>\r\n<td style=\"width: 33.3333%;\">2,60,000</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 33.3333%;\">Rohingya Crisis</td>\r\n<td style=\"width: 33.3333%;\">7,209</td>\r\n<td style=\"width: 33.3333%;\">3,45,557</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n</body>\r\n</html>',1,'2022-01-07 00:54:37','2022-12-06 16:13:12'),(5,'Mother and Child Care',5,'/uploads/story/thumb_image/1643942657_thumbnail_child_care-2.jpg','/uploads/story/banner_image1643942806_thumbnail_Child_Care-1.jpg','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Taslima lost her husband in February to a microbus accident with their baby due in August. Left with another child just 3-year-old and an aged mother-in-law, she could not even fathom what the future holds. Having lost the only earning member of the family, she was stranded financially and left to scrounge money for the upcoming medical expenses of childbirth and rearing another. Amidst this desperate time, Rahima Khala (Aunty) came to her doorstep.&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Rahima Khala (Rahima Khatun) is a Community Health Assistant (CHA) at Grameen Kalyan who goes house to house and conducts medical check-ups, identifies and keeps track of pregnant women and gives healthcare advice in the locality. She is well known and holds a good reputation among the villagers as a capable health worker. Taslima had heard about Rahima Khala and that she works with prominent doctors in a health center named Grameen Kalyan. \"It must be expensive\", she thought. \"Even though it is nearby, I could not possibly afford to go there\".</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">When Rahima Khala stopped by for her medical check-up, she suggested Taslima visit the health center to consult a doctor regarding the pregnancy. Fearful of the expenditure, Taslima discarded the suggestion. However, Rahima Khala informe</span><span lang=\"EN-GB\" style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-GB; mso-fareast-language: EN-AU;\">d </span><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">her about the affordable health care plan provided at Grameen Kalyan, leaving Taslima astonished. Upon comparison, Taslima realized the costs at Grameen Kalyan </span><span lang=\"EN-GB\" style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-ansi-language: EN-GB; mso-fareast-language: EN-AU;\">w</span><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">ere less than half that of a private clinic in the district town she visited for her first pregnancy.&nbsp;&nbsp;&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">After Rahima Khala&rsquo;s insistence, Taslima agreed to go to the health center and was amazed by the service provided. From the initial health assistance to DMF to being ushered to the doctor, everything in primary health care was being coordinated for her in the center.&nbsp; A female doctor was assigned to her who was updated on all of Taslima&rsquo;s medical records and so she only needed to inform the doctor of small medical details. The doctor performed an ultrasound and assured the healthy state of the baby</span> <span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Taslima felt a sense of relief and</span> <span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">contentment from her medical examination visit. She looked at Rahima Khala with a smile of gratitude and began to understand that Grameen Kalyan is beside the people in their health and sickness. She realized she didn\'t have to worry about carrying the burden of a huge medical expense. If only her husband could see this now.&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Grameen Kalyan believes that before, during, and after a newborn enters the world, both the mother and child deserve the utmost attention and care. Not only just providing the right primary health care for new mothers and children, but Grameen Kalyan also works in creating awareness and providing wellness education from home to home in each area under its health center. But when it comes to implementation, the journey at Grameen Kalyan begins with identifying pregnant women in the areas adjacent to each of the established health centers. Following registration of the expecting mothers, community health assistants keep regular updates of the mothers throughout the entire pregnancy and ensure check-up appointments at Grameen Kalyan&rsquo;s health centers.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Each year, Grameen Kalyan provides antenatal care to 100,586+ mothers through camps and health centers. Yet, if any complication arises, Grameen Kalyan health professionals refer the patients to responsible doctors capable of handling such situations without any delay. Grameen Kalyan have qualified and experienced paramedics on-call at all times who can ensure safe delivery in uncomplicated cases. With precaution and safety during this pandemic, Grameen Kalyan is conducting limited deliveries only at certain designated health centers. In the post-delivery state, Grameen Kalyan health professionals work to ensure the newborn\'s health by advising necessary care to be undertaken by families during this time. </span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Starting with an emphasis on exclusive breastfeeding, Grameen Kalyan educate the mothers on effective breastfeeding methods, awareness of child healthcare, and hygiene. </span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">Community Health Assistants do health check-ups at home to detect any early signs of child health problems, such as malnutrition, diarrhoea, pneumonia, among others and usher them to Grameen Kalyan facilities to get treated immediately. </span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span><span style=\"font-size: 16px; color: #000000;\"><span style=\"mso-ascii-font-family: Calibri; mso-fareast-font-family: \'Times New Roman\'; mso-hansi-font-family: Calibri; mso-bidi-font-family: Calibri; mso-ansi-language: EN-AU; mso-fareast-language: EN-AU;\">&nbsp;</span></span></p>\r\n<h3 class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline; text-align: left;\"><span lang=\"EN-GB\" style=\"font-size: 16px;\">From 2012 to 2021</span></h3>\r\n<table class=\"MsoNormalTable\" style=\"height: 65px; width: 100%; border-collapse: collapse; border-style: solid;\" border=\"1\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr style=\"mso-yfti-irow: 0; mso-yfti-firstrow: yes; height: 21.75pt;\">\r\n<td style=\"width: 11.0439%; border: 1pt solid black; padding: 0cm; height: 21px;\" valign=\"bottom\">\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">&nbsp;</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n</td>\r\n<td style=\"width: 7.5643%; border-top: 1pt solid black; border-right: 1pt solid black; border-bottom: 1pt solid black; border-image: initial; border-left: none; padding: 0cm; height: 21px;\">\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline;\"><span style=\"font-size: 16px; color: #000000;\"><span lang=\"EN-GB\" style=\"font-family: Arial, sans-serif;\">2012</span><span style=\"font-family: Arial, sans-serif;\">&nbsp;</span></span></p>\r\n</td>\r\n<td style=\"width: 7.5643%; border-top: 1pt solid black; border-right: 1pt solid black; border-bottom: 1pt solid black; border-image: initial; border-left: none; padding: 0cm; height: 21px;\">\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0cm; line-height: normal; vertical-align: baseline;\"><span sty