insert  into `timelines`(`id`,`title`,`thumb_image`,`created_at`,`updated_at`,`details`) values (1,'1996 - 2000','/uploads/contents/1689849237_grid-1_(1).jpg','2023-07-20 10:33:57','2023-07-20 10:53:09','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div>\r\n<table border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>08 Health centers were Installed</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>Community based Primary Health Care program launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>Domiciliary Service began to operate</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>Satellite Health Program was introduced</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>Introduced Micro Health Insurance</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>30,000+ patients were served in the year of inception</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>Well-being Program was launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>Initiated Emergency Response Program</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</body>\r\n</html>'),(2,'2001 - 2005','/uploads/contents/1689849349_grid-2.jpg','2023-07-20 10:35:49','2023-07-20 10:52:25','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div>\r\n<table border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">14 Health centers were installed</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">Mega Camp (Eye &amp; Medicine) were introduced</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">Dental Service was launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">General Medicine was launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">School Health Program launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">1,35,000+ patients were served</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</body>\r\n</html>'),(3,'2006 - 2010','/uploads/contents/1689849372_grid-3.jpg','2023-07-20 10:36:12','2023-07-20 10:51:41','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div>\r\n<table border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>32 Health Centers was installed</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>Safe Maternity Program was introduced</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>USG (Imaging) Program was introduced</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>EPI Program was introduced</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>Vaccination Program was introduced</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>International Training Program for Health Professionals began</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>2,75,750+ patients were served in 2006</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</body>\r\n</html>'),(4,'2011 - 2015','/uploads/contents/1689849392_grid-4.jpg','2023-07-20 10:36:32','2023-07-20 10:51:03','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div>\r\n<table border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">54 Health Center were installed</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">Diabetes &amp; HTN Program launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">ECG Service launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">Safety Net Program launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">3,30,560+ patients were served</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">Launched Nobin Udyokta Program</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</body>\r\n</html>'),(5,'2016 - 2020','/uploads/contents/1689849406_grid-5.jpg','2023-07-20 10:36:46','2023-07-20 10:49:12','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div>\r\n<table border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>96 Health centers were installed</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>Gynae &amp; Obs Program launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>Eye Care program launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>MBBS Doctors\' camp introduced</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>ENT Care program launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>Telemedicine Program launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>In-House Training Program for Health Professionals</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p>4,50,480+ patients were served</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</body>\r\n</html>'),(6,'2021 - Present','/uploads/contents/1689849484_grid-6.jpg','2023-07-20 10:38:04','2023-07-20 10:49:56','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n</head>\r\n<body>\r\n<div>\r\n<table border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">139 Health Center is in operation</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">X-Ray Program launched</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">Emergency Response during COVID-19 Pandemic</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">COVID-19 Public Awareness Program</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">Food Support/ Relief Program</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">Digital Healthcare Introduced</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"623\">\r\n<p align=\"right\">5,10,500+ patients were served</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</body>\r\n</html>');

/*Table structure for table `upazillas` */

DROP TABLE IF EXISTS `upazillas`;

CREATE TABLE `upazillas` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `bn_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `geo_upazilla_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `district_id` bigint unsigned NOT NULL,
  `url` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `upazillas_district_id_foreign` (`district_id`),
  CONSTRAINT `upazillas_district_id_foreign` FOREIGN KEY (`district_id`) REFERENCES `districts` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=497 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `upazillas` */

